use super::*;
fn setup()->(tempfile::TempDir,Store){let d=tempfile::tempdir().unwrap();let mut s=Store::open(&d.path().join("inventory.db")).unwrap();for code in ["1","2"]{s.execute("stock_entry",json!({"item_code":code,"name":"Screen","model_description":"Phone","quantity":10,"unit_cost_baisa":5000})).unwrap();}(d,s)}
fn sold(s:&mut Store)->String{s.execute("stock_out",json!({"cr_number":"123","lines":[{"item_code":"1","quantity":2,"unit_price_baisa":15000}]})).unwrap();s.snapshot(&json!({})).unwrap()["sale_lines"][0]["id"].as_str().unwrap().into()}
fn ret(id:&str,res:&str,qty:i64)->Value{json!({"password":"1234","line_id":id,"quantity":qty,"resolution":res,"refund_baisa":if res=="refund"{15000*qty}else{0},"extra_baisa":0,"note":"Factory issue","replacement_item_code":"2"})}
#[test]fn non_sales_deduct_fifo_without_cr_or_revenue(){let(_d,mut s)=setup();for p in ["personal","damage"]{s.execute("stock_out",json!({"lines":[{"item_code":"1","quantity":1,"purpose":p}]})).unwrap();}let snap=s.snapshot(&json!({})).unwrap();assert_eq!(snap["summary"]["total_units"],18);assert_eq!(snap["summary"]["monthly_units_sold"],0);assert_eq!(snap["summary"]["monthly_sales_baisa"],0);assert_eq!(snap["summary"]["monthly_personal_cost_baisa"],5000);assert_eq!(snap["summary"]["monthly_damage_cost_baisa"],5000);assert!(snap["sale_lines"][0]["cr_number"].is_null());assert!(s.execute("stock_out",json!({"lines":[{"item_code":"1","quantity":1,"purpose":"damage","unit_price_baisa":20}]})).is_err());}
#[test]fn mixed_lines_require_cr_and_only_sales_contribute_revenue(){let(_d,mut s)=setup();let mut p=json!({"lines":[{"item_code":"1","quantity":1,"unit_price_baisa":15000},{"item_code":"2","quantity":1,"purpose":"damage"}]});assert!(s.execute("stock_out",p.clone()).is_err());p["cr_number"]=json!("123");s.execute("stock_out",p).unwrap();let sn=s.snapshot(&json!({})).unwrap();assert_eq!(sn["summary"]["monthly_units_sold"],1);assert_eq!(sn["summary"]["monthly_sales_baisa"],15000);assert_eq!(sn["summary"]["monthly_profit_baisa"],10000);}
#[test]fn refund_preserves_cr_stock_original_sale_and_is_not_repeatable(){let(_d,mut s)=setup();let id=sold(&mut s);let before=s.snapshot(&json!({})).unwrap();let p=ret(&id,"refund",2);let r=s.execute("damaged_return",p.clone()).unwrap();assert!(Path::new(r["pre_edit_backup"].as_str().unwrap()).exists());let sn=s.snapshot(&json!({})).unwrap();assert_eq!(sn["summary"]["total_units"],before["summary"]["total_units"]);assert_eq!(sn["summary"]["monthly_sales_baisa"],0);assert_eq!(sn["summary"]["monthly_profit_baisa"],-10000);assert_eq!(sn["sale_lines"][0]["revenue_baisa"],30000);assert_eq!(sn["sale_lines"][0]["cr_number"],"123");assert_eq!(sn["sale_lines"][0]["returned_quantity"],2);assert!(s.execute("damaged_return",p).is_err());assert!(s.execute("delete_record",json!({"kind":"sale","id":id,"password":"1234","confirmed":true})).is_err());validate_database(&s.conn).unwrap();}
#[test]fn replacement_has_no_second_charge_and_rolls_back_on_shortfall(){let(_d,mut s)=setup();let id=sold(&mut s);let mut p=ret(&id,"replacement",1);p["replacement_item_code"]=json!("999");let before=s.snapshot(&json!({})).unwrap();assert!(s.execute("damaged_return",p.clone()).is_err());assert_eq!(s.snapshot(&json!({})).unwrap(),before);p["replacement_item_code"]=json!("2");s.execute("damaged_return",p).unwrap();let sn=s.snapshot(&json!({})).unwrap();assert_eq!(sn["summary"]["total_units"],17);assert_eq!(sn["summary"]["monthly_units_sold"],2);assert_eq!(sn["summary"]["monthly_sales_baisa"],30000);assert_eq!(sn["summary"]["monthly_profit_baisa"],15000);assert_eq!(sn["sale_lines"][0]["purpose"],"replacement");assert_eq!(sn["sale_lines"][0]["cr_number"],"123");}
#[test]fn pending_can_be_resolved_once_with_same_quantity_and_password(){let(_d,mut s)=setup();let id=sold(&mut s);let mut p=ret(&id,"pending",1);p["password"]=json!("wrong");assert!(s.execute("damaged_return",p.clone()).is_err());p["password"]=json!("1234");let r=s.execute("damaged_return",p).unwrap();let mut p=ret(&id,"refund",1);p["return_id"]=r["id"].clone();s.execute("damaged_return",p.clone()).unwrap();assert!(s.execute("damaged_return",p).is_err());assert_eq!(s.snapshot(&json!({})).unwrap()["summary"]["monthly_sales_baisa"],15000);}
#[test]fn refund_caps_and_partial_quantities_are_enforced(){let(_d,mut s)=setup();let id=sold(&mut s);let mut p=ret(&id,"refund",1);p["refund_baisa"]=json!(15001);assert!(s.execute("damaged_return",p.clone()).is_err());p["refund_baisa"]=json!(14000);s.execute("damaged_return",p).unwrap();s.execute("damaged_return",ret(&id,"refund",1)).unwrap();assert!(s.execute("damaged_return",ret(&id,"refund",1)).is_err());}
#[test]fn v2_upgrade_preserves_rowids_records_and_old_backup_restore(){let d=tempfile::tempdir().unwrap();let p=d.path().join("v2.db");let c=Connection::open(&p).unwrap();c.execute_batch(SCHEMA_V2).unwrap();c.execute("INSERT INTO products(rowid,id,item_code,name,model_description,created_at,updated_at) VALUES(7,'p','1','Screen','Phone',?1,?1)",[now()]).unwrap();drop(c);let mut s=Store::open(&p).unwrap();assert_eq!(version(&s.conn).unwrap(),3);assert_eq!(s.conn.query_row("SELECT rowid FROM products",[],|r|r.get::<_,i64>(0)).unwrap(),7);let b=d.path().join("new.db");s.backup(&b).unwrap();s.restore(&b).unwrap();validate_database(&s.conn).unwrap();assert_eq!(s.snapshot(&json!({})).unwrap()["products"].as_array().unwrap().len(),1);}
#[test]fn backup_restore_keeps_all_return_and_purpose_records(){let(d,mut s)=setup();let id=sold(&mut s);s.execute("damaged_return",ret(&id,"replacement",1)).unwrap();let before=s.snapshot(&json!({})).unwrap();let b=d.path().join("backup.db");s.backup(&b).unwrap();let mut other=Store::open(&d.path().join("other.db")).unwrap();other.restore(&b).unwrap();assert_eq!(other.snapshot(&json!({})).unwrap(),before);}

#[test]fn non_sale_mistakes_can_be_corrected_and_deleted_with_password(){let(_d,mut s)=setup();s.execute("stock_out",json!({"lines":[{"item_code":"1","quantity":2,"purpose":"damage"}]})).unwrap();let sn=s.snapshot(&json!({})).unwrap();let l=&sn["sale_lines"][0];s.execute("edit_record",json!({"password":"1234","kind":"sale","id":l["id"],"changes":{"item_code":"1","quantity":1,"unit_price_baisa":0,"created_at":l["created_at"]}})).unwrap();assert_eq!(s.snapshot(&json!({})).unwrap()["summary"]["total_units"],19);s.execute("delete_record",json!({"password":"1234","kind":"sale","id":l["id"],"confirmed":true})).unwrap();assert_eq!(s.snapshot(&json!({})).unwrap()["summary"]["total_units"],20);}

#[test]fn v2_populated_upgrade_and_restore_preserve_original_fifo_and_source(){
 let d=tempfile::tempdir().unwrap();let old=d.path().join("old.db");let c=Connection::open(&old).unwrap();c.execute_batch(SCHEMA_V2).unwrap();let time=now();
 c.execute("INSERT INTO products(rowid,id,item_code,name,model_description,created_at,updated_at) VALUES(7,'p','1','Screen','Phone',?1,?1)",[&time]).unwrap();
 c.execute("INSERT INTO stock_entries(rowid,id,product_id,quantity,unit_cost_baisa,created_at) VALUES(11,'e','p',3,5000,?1)",[&time]).unwrap();
 c.execute("INSERT INTO sales(rowid,id,cr_number,created_at,revenue_baisa,cost_baisa,profit_baisa) VALUES(8,'s','123',?1,30000,10000,20000)",[&time]).unwrap();
 c.execute("INSERT INTO sale_lines(rowid,id,sale_id,product_id,item_code,product_name,model_description,quantity,unit_price_baisa,revenue_baisa,cost_baisa,profit_baisa) VALUES(12,'l','s','p','1','Screen','Phone',2,15000,30000,10000,20000)",[]).unwrap();
 c.execute("INSERT INTO fifo_allocations(line_id,entry_id,quantity) VALUES('l','e',2)",[]).unwrap();validate_database(&c).unwrap();drop(c);
 let source=fs::read(&old).unwrap();let mut target=Store::open(&d.path().join("target.db")).unwrap();target.restore(&old).unwrap();assert_eq!(fs::read(&old).unwrap(),source);assert_eq!(target.snapshot(&json!({})).unwrap()["summary"]["monthly_sales_baisa"],30000);assert_eq!(target.snapshot(&json!({})).unwrap()["summary"]["total_units"],1);assert_eq!(target.conn.query_row("SELECT rowid FROM sale_lines",[],|r|r.get::<_,i64>(0)).unwrap(),12);target.execute("damaged_return",ret("l","refund",1)).unwrap();validate_database(&target.conn).unwrap();
}

#[test]fn refund_is_accounted_in_settlement_month_not_original_sale_month(){
 let(_d,mut s)=setup();let id=sold(&mut s);let sn=s.snapshot(&json!({})).unwrap();let l=&sn["sale_lines"][0];
 let old=if Local::now().format("%Y-%m").to_string()=="2025-01"{"2024-01-01T12:00:00Z"}else{"2025-01-01T12:00:00Z"};
 s.execute("edit_record",json!({"password":"1234","kind":"sale","id":id,"changes":{"item_code":"1","quantity":2,"unit_price_baisa":15000,"cr_number":"123","created_at":old}})).unwrap();
 s.execute("damaged_return",ret(l["id"].as_str().unwrap(),"refund",1)).unwrap();let current=s.snapshot(&json!({})).unwrap();assert_eq!(current["summary"]["monthly_units_sold"],0);assert_eq!(current["summary"]["monthly_sales_baisa"],-15000);let old=s.snapshot(&json!({"month":&old[..7]})).unwrap();assert_eq!(old["summary"]["monthly_sales_baisa"],30000);
}

#[test]fn invalid_return_relationship_in_backup_is_rejected_without_replacing_live_data(){let(d,mut s)=setup();let id=sold(&mut s);s.execute("damaged_return",ret(&id,"replacement",1)).unwrap();let b=d.path().join("tampered.db");s.backup(&b).unwrap();let c=Connection::open(&b).unwrap();c.execute_batch("DROP TRIGGER return_no_update;").unwrap();c.execute("UPDATE damaged_returns SET quantity=9",[]).unwrap();let reference=Connection::open_in_memory().unwrap();reference.execute_batch(SCHEMA).unwrap();let guard:String=reference.query_row("SELECT sql FROM sqlite_master WHERE name='return_no_update'",[],|r|r.get(0)).unwrap();c.execute_batch(&guard).unwrap();drop(c);let before=s.snapshot(&json!({})).unwrap();assert!(s.restore(&b).is_err());assert_eq!(s.snapshot(&json!({})).unwrap(),before);}
